  constructor(){ this.fixtureMode = new URLSearchParams(window.location.search).get('fixture') === 'story-review'; this.restore(); if(this.fixtureMode) this.loadStoryReviewFixture(); this.loadCatalogues(); this.loadSavedStories(); if(this.sessionId){this.http.get<any>(`/api/v1/intelligence/workflow/studio-sessions/${this.sessionId}`).subscribe({next:s=>{this.restoreServer(s);this.changeDetector.markForCheck();},error:()=>{}});} this.http.get<any>('/api/v1/intelligence/workflow/creative-role/readiness').subscribe({next:r=>{this.readiness=r;this.changeDetector.markForCheck();},error:()=>this.error='DeepSeek is not ready. Check the configured connection.'}); }
